                installCustomSeekBar();
                setPlayerStatus("m3u8 ready", "Plyr + HLS.js loaded" + (heights.length ? " • " + heights.join("p / ") + "p" : "") + ". Timeline enabled.", false);
                setStatus("m3u8 loaded. Timeline enabled.");
